import{H as e,V as t,et as n,j as r}from"./chunks/framework.Dj60FFN6.js";var i=JSON.parse(`{"title":"I paradossi","description":"","frontmatter":{},"headers":[],"relativePath":"lezioni/c_analisi/ca/cab.md","filePath":"lezioni/c_analisi/ca/cab.md"}`),a={name:`lezioni/c_analisi/ca/cab.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="i-paradossi" tabindex="-1">I paradossi <a class="header-anchor" href="#i-paradossi" aria-label="Permalink to “I paradossi”">​</a></h1><p>Della poca praticità del concetto di punto si erano già accorti gli antichi, ad esempio Zenone enunciò alcuni paradossi irresolubili con la matematica tradizionale: il più celebre è quello di Achille (il guerriero più veloce dell&#39;antichità tanto da meritarsi il soprannome di Piè Veloce) e della tartaruga.</p><p>Achille e la tartaruga decidono di fare una gara di corsa, ma siccome Achille è più veloce dà alla tartaruga un vantaggio di ad esempio <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>100</mn></mrow><annotation encoding="application/x-tex">100</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">100</span></span></span></span> metri, chi vincerà?</p><p><strong>Questo il ragionamento di Zenone:</strong></p><blockquote><p>Mentre Achille percorre i <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>100</mn></mrow><annotation encoding="application/x-tex">100</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">100</span></span></span></span> metri che lo separano dalla tartaruga questa fa <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>10</mn></mrow><annotation encoding="application/x-tex">10</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">10</span></span></span></span> metri, mentre Achille percorre quei <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>10</mn></mrow><annotation encoding="application/x-tex">10</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">10</span></span></span></span> metri la tartaruga percorre <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>1</mn></mrow><annotation encoding="application/x-tex">1</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">1</span></span></span></span> metro, mentre Achille percorre il <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>1</mn></mrow><annotation encoding="application/x-tex">1</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">1</span></span></span></span> metro la tartaruga percorre <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>10</mn></mrow><annotation encoding="application/x-tex">10</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">10</span></span></span></span> centimetri...</p></blockquote><p>Capisci che ragionando così, essendo lo spazio infinitamente divisibile, Achille non riuscirà mai a superare la tartaruga.</p><p>Qual è l&#39;errore nel ragionamento? Il fatto di confondere lo spazio fisico (che non è infinitamente divisibile) con lo spazio matematico infinitamente divisibile.</p><p>Per farti capire che lo spazio fisico non è infinitamente divisibile prova a pensare che per trovare la circonferenza della terra basta moltiplicarne il raggio per <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>2</mn><mi>π</mi></mrow><annotation encoding="application/x-tex">2\\pi</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">2</span><span class="mord mathnormal" style="margin-right:0.0359em;">π</span></span></span></span>; allora se io prendo il raggio terrestre in metri e <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>π</mi></mrow><annotation encoding="application/x-tex">\\pi</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">π</span></span></span></span> con <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>10</mn></mrow><annotation encoding="application/x-tex">10</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">10</span></span></span></span> cifre decimali trovo la circonferenza terrestre con un&#39;approssimazione superiore al diametro di un atomo!</p><p>Non essendo lo spazio fisico infinitamente divisibile non sarà possibile usarvi il concetto di punto, ma un concetto più efficace anche se più grossolano:</p><h2 id="l-intervallo" tabindex="-1">L&#39;intervallo <a class="header-anchor" href="#l-intervallo" aria-label="Permalink to “L&#39;intervallo”">​</a></h2>`,10)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};